insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_69_v1'
from (values
('127.452.d.1',3,'An engineer discovers that a product she designed could injure users if a part fails. The ethical action is to:','["report the risk and fix it", "keep quiet to protect sales", "blame the user", "wait for a lawsuit"]'::jsonb,0,'Public safety comes before company convenience.','original'),
('127.452.d.1',4,'A practicum student is asked to copy another company''s confidential design for a client. Professional ethics says the student should:','["sell it to a rival", "decline and tell a supervisor", "copy it quickly", "change only the title"]'::jsonb,1,'Confidential designs belong to their owners.','original'),
('127.452.d.2.A',3,'A student who wants to meet working engineers and attend design competitions could look into the National Society of Professional Engineers or:','["a cooking class", "a movie club", "a student engineering club", "a fan page"]'::jsonb,2,'Engineering organizations offer networking and events.','original'),
('127.452.d.2.A',4,'Joining a professional engineering society as a student can help most with:','["free tuition always", "avoiding teamwork", "skipping exams", "networking and mentoring"]'::jsonb,3,'Societies connect students to professionals.','original'),
('127.452.d.2.B',3,'An engineer who plans roads and bridges is serving the public mainly through:','["civil engineering", "fashion design", "culinary arts", "film editing"]'::jsonb,0,'Civil engineers design public infrastructure.','original'),
('127.452.d.2.B',4,'A mechanical engineer and an electrical engineer on the same robot project show that engineering roles:','["never overlap", "work together on one product", "avoid each other", "compete for credit"]'::jsonb,1,'Products need several specialties.','original'),
('127.452.d.2.C',3,'A student chapter organizes a bridge-building contest for local middle schools. This activity helps its community by:','["closing roads", "banning tools", "encouraging interest in engineering", "raising rent"]'::jsonb,2,'Outreach builds interest in STEM.','original'),
('127.452.d.2.C',4,'A professional society that publishes safety standards benefits the public because it:','["raises prices only", "limits hiring randomly", "hides test results", "sets shared expectations for quality"]'::jsonb,3,'Standards protect users.','original'),
('127.452.d.3.A',3,'Before designing a solar charger for a school, a student collects facts about sunlight, batteries, and costs. This is:','["technical research", "advertising", "decoration", "guessing"]'::jsonb,0,'Research gathers information first.','original'),
('127.452.d.3.A',4,'A student finds that no source explains how much power a small panel makes in shade. The student has found a:','["finished design", "gap in the information", "safety award", "budget refund"]'::jsonb,1,'Gaps show where more testing is needed.','original'),
('127.452.d.3.B',3,'A student brainstorms many unusual ways to carry water across a field without a pump. The student is working to find:','["a final grade", "a rental car", "creative solutions", "a tax form"]'::jsonb,2,'Brainstorming generates ideas.','original'),
('127.452.d.3.B',4,'A student at a work site suggests a cheaper way to organize tools that saves the crew time. This is an:','["accident report", "time sheet", "code violation", "innovative solution"]'::jsonb,3,'New ideas can improve workplaces.','original'),
('127.452.d.3.C',3,'A team sketches three versions of a shelf bracket and compares the strength, cost, and weight of each. They are:','["analyzing alternative designs", "ignoring the problem", "hiding results", "skipping research"]'::jsonb,0,'Comparison supports choosing the best design.','original'),
('127.452.d.3.C',4,'A design matrix gives each design a score for cost, safety, and ease of building. Its main purpose is to:','["avoid testing", "compare options fairly", "delay the project", "pick a favorite color"]'::jsonb,1,'Matrices make comparisons objective.','original'),
('127.452.d.3.D',3,'After testing a prototype, a student reports to the mentor how well it solved the original problem. This is:','["making a logo", "hiding the failures", "evaluating the solution", "starting over blindly"]'::jsonb,2,'Evaluation judges a solution against goals.','original'),
('127.452.d.3.D',4,'When a prototype misses its goal, a good report states what failed and what should change in the:','["parking lot", "school calendar", "lunch menu", "next version"]'::jsonb,3,'Reports guide improvement.','original'),
('127.452.d.4.A',3,'A team member who always keeps promises and tells the truth shows the leadership trait of:','["trustworthiness", "laziness", "gossip", "pride"]'::jsonb,0,'Trust is a leadership quality.','original'),
('127.452.d.4.A',4,'A supervisor who stays calm and encouraging when a project hits a snag is showing a positive:','["invoice", "attitude", "password", "accident"]'::jsonb,1,'Attitude shapes team morale.','original'),
('127.452.d.4.B',3,'On a design team, each member shares ideas, listens to others, and does a fair share. These are traits of good:','["isolation", "delay", "teamwork", "rivalry"]'::jsonb,2,'Teamwork needs cooperation.','original'),
('127.452.d.4.B',4,'A team member disagrees with a plan and explains the reasons politely. This shows teamwork because the member:','["quits the team", "ignores the plan", "shouts at others", "contributes while respecting others"]'::jsonb,3,'Respectful disagreement helps teams.','original'),
('127.452.d.4.C',3,'Each member of a robot team has a task, and one member skips a task. The group''s work is hurt because shared work depends on:','["every person''s responsibility", "uniforms", "weather", "luck alone"]'::jsonb,0,'Teams depend on individual follow-through.','original'),
('127.452.d.4.C',4,'A student promises to finish wiring by Friday so the team can test on Monday. Meeting the promise shows:','["delay", "accountability", "secrecy", "avoidance"]'::jsonb,1,'Accountability supports the group.','original'),
('127.452.d.4.D',3,'Arriving on time, finishing work before the deadline, and showing respect to coworkers are strategies that build:','["less training", "extra vacation", "a good professional reputation", "a longer lunch"]'::jsonb,2,'Professional habits earn trust.','original'),
('127.452.d.4.D',4,'An employee who often misses deadlines on engineering drawings is most likely to harm the:','["building color", "office plants", "street names", "team''s schedule"]'::jsonb,3,'Late work delays others.','original'),
('127.452.d.4.E',3,'A student interested in engineering joins a robotics team after school. This is an example of an:','["extracurricular activity", "required class", "paid contract", "state law"]'::jsonb,0,'Clubs add experience outside class.','original'),
('127.452.d.4.E',4,'Participating in an engineering competition outside class can help a student build:','["a shorter school day", "leadership and technical skills", "a driver''s license", "free equipment only"]'::jsonb,1,'Competitions build skills.','original'),
('127.452.d.5.A',3,'A student uses the words tolerance, load, and prototype correctly when explaining a design to a mentor. This is applying:','["slang only", "random terms", "technical vocabulary", "nicknames"]'::jsonb,2,'Correct vocabulary shows understanding.','original'),
('127.452.d.5.A',4,'An engineer says a beam can support a larger force before bending. Using the correct term for that ability, the engineer says the beam has more:','["humor", "flavor", "fashion", "strength"]'::jsonb,3,'Strength is a technical concept.','original'),
('127.452.d.5.B',3,'When explaining a circuit to a customer who is not an engineer, a professional communicator would use:','["clear words with simple examples", "as much jargon as possible", "only formulas", "a whisper"]'::jsonb,0,'Communication fits the audience.','original'),
('127.452.d.5.B',4,'In a meeting, an engineer who pauses, speaks clearly, and defines unusual terms is using professional:','["gaming skills", "communication skills", "accounting skills", "cooking skills"]'::jsonb,1,'Clear speech helps listeners.','original'),
('127.452.d.5.C',3,'A student reads an installation manual and a data sheet before wiring a motor. These are examples of:','["comic strips", "novels", "informational texts", "poems"]'::jsonb,2,'Manuals and data sheets inform tasks.','original'),
('127.452.d.5.C',4,'A table in a data sheet lists the maximum voltage a part can handle. A student uses it to:','["name the product", "pick a logo", "choose paint", "avoid damaging the part"]'::jsonb,3,'Specifications set safe limits.','original'),
('127.452.d.5.D',3,'A coworker crosses his arms, looks away, and gives short answers when asked about a plan. These are examples of:','["nonverbal cues", "written words", "legal terms", "math symbols"]'::jsonb,0,'Body language sends messages.','original'),
('127.452.d.5.D',4,'Making eye contact and nodding while a mentor explains a task shows that you are:','["leaving", "paying attention", "angry", "bored"]'::jsonb,1,'Positive cues show engagement.','original'),
('127.452.d.5.E',3,'After a supervisor gives instructions, the student repeats them in her own words to make sure she understood. This is:','["interrupting", "daydreaming", "active listening", "arguing"]'::jsonb,2,'Paraphrasing confirms meaning.','original'),
('127.452.d.5.E',4,'Asking a clarifying question about an unclear step on a drawing is a good way to:','["impress the boss with silence", "avoid the task", "slow the team on purpose", "prevent a costly mistake"]'::jsonb,3,'Clarifying prevents errors.','original'),
('127.452.d.6.A',3,'After a practicum, a student lists skills she did well and skills she still needs to practice. This is a self-:','["assessment", "invoice", "advertisement", "warranty"]'::jsonb,0,'Self-assessment finds strengths and weaknesses.','original'),
('127.452.d.6.A',4,'Knowing that her CAD skills are strong but her report writing is weak, a student plans extra practice in:','["buying software", "writing reports", "drawing more", "skipping class"]'::jsonb,1,'Plans target weaknesses.','original'),
('127.452.d.6.C',3,'A student shows her portfolio to a panel of engineers and a future employer. Giving it to this group is called:','["trading the portfolio", "deleting the portfolio", "presenting the portfolio", "hiding the portfolio"]'::jsonb,2,'Stakeholders review portfolios.','original'),
('127.452.d.6.C',4,'Interested stakeholders for a student''s portfolio include employers, teachers, and:','["random strangers only", "pets", "no one", "college admissions staff"]'::jsonb,3,'Portfolios support college and career goals.','original'),
('127.452.d.6.B.i',3,'A portfolio can include proof that a student has earned a certain skill, such as an industry-based:','["certification", "coupon", "nickname", "rumor"]'::jsonb,0,'Certifications show attainment.','original'),
('127.452.d.6.B.i',4,'A copy of a state-recognized credential in a portfolio helps show the student''s attainment of:','["free supplies", "technical knowledge", "a bigger locker", "a long vacation"]'::jsonb,1,'Credentials show learning.','original'),
('127.452.d.6.B.ii',3,'A portfolio may list the licenses a student holds, such as a:','["coupon book", "library card", "drone pilot license", "movie ticket"]'::jsonb,2,'Licenses show authorized skills.','original'),
('127.452.d.6.B.ii',4,'Licensures and certifications in a portfolio tell employers what the student is:','["too tired for", "afraid of", "paid less for", "qualified to do"]'::jsonb,3,'These prove qualifications.','original'),
('127.452.d.6.B.iii',3,'A portfolio page that lists a science fair prize and a robotics trophy shows the student''s:','["recognitions", "rumors", "complaints", "debts"]'::jsonb,0,'Awards belong in portfolios.','original'),
('127.452.d.6.B.iii',4,'A thank-you letter from a community partner praising a student''s work could be included as a:','["warning", "recognition of service", "contract penalty", "bill"]'::jsonb,1,'Letters document recognition.','original'),
('127.452.d.6.B.iv',3,'A portfolio can describe a student''s extended learning experiences, such as an internship or a:','["movie night", "shopping trip", "job shadowing day", "school dance"]'::jsonb,2,'Learning outside class counts.','original'),
('127.452.d.6.B.iv',4,'A mentor''s summary of what the student learned in a summer engineering camp is an example of:','["a fee notice", "a grade appeal", "a rumor", "extended learning"]'::jsonb,3,'Camps and internships extend learning.','original'),
('127.452.d.6.B.v',3,'A short summary of a student''s practicum project placed in the portfolio is called an:','["abstract", "warranty", "invoice", "coupon"]'::jsonb,0,'Abstracts summarize a project.','original'),
('127.452.d.6.B.v',4,'An abstract of a practicum project should include the problem, the method, and the:','["lunch menu", "results", "bus route", "hallway map"]'::jsonb,1,'Abstracts capture key points.','original'),
('127.452.d.6.B.vi',3,'A one-page document listing a student''s education, skills, and work experience is a:','["timetable", "warranty", "resume", "receipt"]'::jsonb,2,'Resumes summarize qualifications.','original'),
('127.452.d.6.B.vi',4,'A resume for an engineering practicum should list relevant skills such as CAD, soldering, and:','["pet names", "gaming scores", "favorite songs", "teamwork"]'::jsonb,3,'Relevant skills belong on a resume.','original'),
('127.452.d.6.B.vii',3,'A photo of a student''s finished prototype with the design drawings is a good:','["sample of work", "menu", "rumor", "bill"]'::jsonb,0,'Work samples show ability.','original'),
('127.452.d.6.B.vii',4,'Including drawings, code, or photos of completed projects helps an employer see the student''s:','["hobbies only", "actual skills", "height", "favorite foods"]'::jsonb,1,'Evidence supports claims.','original'),
('127.452.d.6.B.viii',3,'A supervisor''s written review of a student''s practicum performance is an:','["coupon", "advertisement", "evaluation form", "menu"]'::jsonb,2,'Evaluations show performance.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_69_v1'
from (values
('127.452.d.6.B.viii',4,'Including a positive supervisor evaluation in a portfolio supports a student''s claims about her:','["music taste", "travel plans", "pet care", "work habits and skills"]'::jsonb,3,'Third-party reviews add credibility.','original'),
('127.452.d.7.A',3,'A student builds a slide deck with charts and photos to show the results of a practicum project. This is a professional:','["presentation", "warranty", "receipt", "rumor"]'::jsonb,0,'Presentations communicate work.','original'),
('127.452.d.7.A',4,'To keep slides easy to read in a professional presentation, a student should use short text and:','["tiny fonts", "clear visuals", "random colors", "every detail"]'::jsonb,1,'Slides support the speaker.','original'),
('127.452.d.7.B',3,'Before presenting a design, the student asks who will be listening. Identifying the audience helps decide the:','["bus schedule", "room paint", "level of detail", "lunch menu"]'::jsonb,2,'Audience shapes content.','original'),
('127.452.d.7.B',4,'Scheduling a time, room, and equipment with a school panel is part of coordinating the:','["end of the semester", "closing of the lab", "hiring of a coach", "presentation of findings"]'::jsonb,3,'Logistics make presentations run smoothly.','original'),
('127.452.d.7.C',3,'A presenter who speaks clearly, makes eye contact, and keeps points brief is presenting in a:','["professional manner", "random manner", "casual manner", "hidden manner"]'::jsonb,0,'Delivery shapes impact.','original'),
('127.452.d.7.C',4,'A presenter shortens a long explanation of test data into three key points. This is using:','["silence", "concise language", "longer sentences", "slang"]'::jsonb,1,'Brevity helps listeners.','original'),
('127.452.d.7.D',3,'After a presentation, a panelist suggests adding a cost chart. The student treats the comment as:','["a joke", "an insult to ignore", "feedback to analyze", "a final grade"]'::jsonb,2,'Feedback guides improvement.','original'),
('127.452.d.7.D',4,'The best use of feedback from a presentation is to decide what to change for the:','["closed project", "previous report", "last year''s class", "next presentation"]'::jsonb,3,'Feedback is for improving future work.','original'),
('127.453.d.1',3,'A senior engineer is asked to sign off on a bridge inspection she did not perform. Engineering ethics says she should:','["refuse to certify work she did not check", "let a friend sign for her", "sign to save time", "sign and hope it is fine"]'::jsonb,0,'Engineers certify only work they verified.','original'),
('127.453.d.1',4,'A company asks a student engineer to report test results that are better than the real data. The ethical response is to:','["delete the weak tests", "report the true results", "round everything up", "hide the data sheet"]'::jsonb,1,'Honest data is a core duty.','original'),
('127.453.d.2.A',3,'To learn about licensing exams and mentoring programs, an advanced student could contact a state board or a professional society such as:','["a sports league", "a fan club", "a local engineering society chapter", "a food truck"]'::jsonb,2,'Professional groups offer licensing guidance.','original'),
('127.453.d.2.A',4,'A student who attends a society meeting to hear working engineers speak gains information about:','["tax filing only", "vacation rentals", "fashion trends", "career paths in the field"]'::jsonb,3,'Meetings expose students to careers.','original'),
('127.453.d.2.B',3,'An engineer who designs electrical power grids and an engineer who designs ventilation systems for the same building show that roles in a project are:','["specialized but connected", "separate forever", "unnecessary", "identical"]'::jsonb,0,'Specialties must coordinate.','original'),
('127.453.d.2.B',4,'Chemical engineers help the public by designing safe processes for making fuels, medicines, and:','["greeting cards", "clean water treatments", "video games", "board games"]'::jsonb,1,'Chemical engineering serves public needs.','original'),
('127.453.d.2.C',3,'A student chapter donates repaired computers to a shelter. This shows how a student organization can serve its:','["rivals", "competitors", "community", "landlord"]'::jsonb,2,'Service projects benefit communities.','original'),
('127.453.d.2.C',4,'A professional organization that runs scholarships for future engineers is helping the profession by:','["limiting access", "lowering standards", "ending research", "growing the next generation"]'::jsonb,3,'Scholarships support new engineers.','original'),
('127.453.d.3.A',3,'An advanced student reads journal articles and test reports before choosing a material for a water filter. This step is:','["technical research", "decoration", "entertainment", "marketing"]'::jsonb,0,'Evidence guides design choices.','original'),
('127.453.d.3.A',4,'After reviewing sources, a student notices that no one has tested the filter at very low temperatures. Finding this missing information is identifying a:','["price drop", "knowledge gap", "safety win", "completed task"]'::jsonb,1,'Gaps direct new testing.','original'),
('127.453.d.3.B',3,'A student at an internship invents a clip that lets cables be moved without tools. Coming up with this new idea is:','["copying a patent", "avoiding the problem", "developing an innovative solution", "filing a complaint"]'::jsonb,2,'Innovation solves real problems.','original'),
('127.453.d.3.B',4,'An intern spots that workers waste time hunting for parts and designs a labeled shelf. This shows creativity applied to a:','["school dance", "music class", "holiday", "work-site problem"]'::jsonb,3,'Work-based problems call for creative fixes.','original'),
('127.453.d.3.C',3,'Two intern teams build different ramps for loading a truck. A mentor asks them to compare the safety, cost, and speed of the two ramps. This is:','["comparing alternative designs", "picking the prettier one", "ignoring costs", "tossing a coin"]'::jsonb,0,'Criteria-based comparison finds the better option.','original'),
('127.453.d.3.C',4,'Choosing the best of several designs should be based on criteria and constraints rather than on:','["budget limits", "personal preference alone", "safety codes", "test data"]'::jsonb,1,'Decisions should be evidence based.','original'),
('127.453.d.3.D',3,'At the end of an internship, a student shows the company how her new fixture reduced assembly time. She is presenting an:','["random guess", "unfinished sketch", "evaluated solution", "tax record"]'::jsonb,2,'Results prove value.','original'),
('127.453.d.3.D',4,'To show a solution worked, an intern compares the time per part before and after the change. This is evaluating with:','["decoration", "rumors", "opinions only", "measured data"]'::jsonb,3,'Data supports evaluation.','original'),
('127.453.d.4.A',3,'An intern who shares credit with the team, keeps a positive attitude, and admits mistakes shows the leadership quality of:','["integrity", "secrecy", "pride", "delay"]'::jsonb,0,'Integrity builds trust.','original'),
('127.453.d.4.A',4,'A project lead who gives clear directions, listens to ideas, and treats everyone fairly is showing strong:','["rule breaking", "leadership characteristics", "gossip habits", "avoidance habits"]'::jsonb,1,'Good leaders communicate and respect others.','original'),
('127.453.d.4.B',3,'In a group project, one student gathers parts, another tests, and a third writes the report. The group works well because members:','["avoid each other", "work alone in secret", "divide tasks and cooperate", "compete for the same job"]'::jsonb,2,'Cooperation divides work.','original'),
('127.453.d.4.B',4,'A team that settles disagreements by discussing evidence and then voting is showing effective:','["avoidance", "bullying", "laziness", "collaboration"]'::jsonb,3,'Collaboration solves conflicts.','original'),
('127.453.d.4.C',3,'A team''s final report is late because one member did not send his section. The problem came from an unmet:','["individual responsibility", "power outage", "weather event", "software update"]'::jsonb,0,'Each person''s part affects the whole.','original'),
('127.453.d.4.C',4,'Keeping a shared checklist of who is doing which task helps a group by tracking:','["parking spaces", "individual and group duties", "movie times", "lunch orders"]'::jsonb,1,'Checklists make responsibilities visible.','original'),
('127.453.d.4.D',3,'A student keeps a planner, finishes drawings a day before they are due, and thanks coworkers. These habits build:','["confusion", "isolation", "professional success", "procrastination"]'::jsonb,2,'Reliable habits support careers.','original'),
('127.453.d.4.D',4,'A supervisor is most likely to trust an intern who consistently:','["works only alone", "arrives late but apologizes", "talks over others", "meets deadlines and shows respect"]'::jsonb,3,'Reliability earns trust.','original'),
('127.453.d.4.E',3,'A student enters a state engineering design competition with classmates. Joining such a contest is a way to take part in:','["extracurricular opportunities", "required exams", "mandatory chores", "state taxes"]'::jsonb,0,'Contests extend learning.','original'),
('127.453.d.4.E',4,'Serving as an officer in a school engineering club helps a student practice:','["missing deadlines", "leadership", "skipping meetings", "avoiding work"]'::jsonb,1,'Officer roles build leadership.','original'),
('127.453.d.5.A',3,'An intern uses the correct terms for stress, strain, and factor of safety when she explains a test to engineers. She is applying:','["slang only", "jokes", "content knowledge and vocabulary", "guesswork"]'::jsonb,2,'Precision shows mastery.','original'),
('127.453.d.5.A',4,'Using a word like torque correctly instead of saying thing that twists helps a student sound:','["rushed", "careless", "unclear", "professional and precise"]'::jsonb,3,'Precise vocabulary helps communication.','original'),
('127.453.d.5.B',3,'An intern writes a clear email to a supplier that includes the part number, quantity, and delivery date. This is:','["professional written communication", "a casual text", "a rumor", "a social post"]'::jsonb,0,'Complete messages avoid confusion.','original'),
('127.453.d.5.B',4,'In a technical report, an intern defines each abbreviation the first time it appears so the reader can:','["print the document", "follow the document", "laugh at the document", "skip the document"]'::jsonb,1,'Defining terms helps readers.','original'),
('127.453.d.5.C',3,'A student reads a building code table and a materials report to choose a safe beam size. These texts help her to:','["decorate a room", "pick a color", "make an informed decision", "order lunch"]'::jsonb,2,'Technical texts guide decisions.','original'),
('127.453.d.5.C',4,'A student reads a graph in a report and sees that strength drops as temperature rises. She has interpreted the graph to find a:','["page number", "chapter title", "author name", "relationship between variables"]'::jsonb,3,'Graphs show relationships.','original'),
('127.453.d.5.D',3,'A client looks at his watch and sighs while the intern explains a plan. The intern should read these cues and:','["shorten and refocus the explanation", "keep talking at length", "leave the room", "argue with the client"]'::jsonb,0,'Reading cues helps adjust a message.','original'),
('127.453.d.5.D',4,'Standing upright, speaking calmly, and shaking hands firmly in a job interview are positive:','["math skills", "nonverbal behaviors", "written skills", "coding skills"]'::jsonb,1,'Body language supports a message.','original'),
('127.453.d.5.E',3,'During a safety briefing, an intern takes notes and asks a question about a step she did not understand. This shows:','["avoiding the topic", "passive resistance", "active listening", "distraction"]'::jsonb,2,'Notes and questions confirm understanding.','original'),
('127.453.d.5.E',4,'To be sure a message was received correctly, a good listener summarizes it and asks:','["for a day off", "for a new job", "for a prize", "whether the summary is right"]'::jsonb,3,'Checking prevents misunderstandings.','original'),
('127.453.d.6.A',3,'At the end of the practicum, a student rates her skills in drafting, teamwork, and presentation, and sets goals for the weakest. She is doing an honest:','["self-evaluation", "advertisement", "copy of a friend''s list", "audit of a stranger"]'::jsonb,0,'Self-evaluation guides growth.','original'),
('127.453.d.6.A',4,'A student compares her mentor''s review with her own rating and finds she overrated her math skills. The best next step is to:','["blame the mentor", "plan a way to improve", "drop the course", "hide the review"]'::jsonb,1,'Feedback should inform a plan.','original'),
('127.453.d.6.C',3,'A student presents her portfolio at a spring showcase for community leaders. The showcase audience is made up of:','["only classmates", "no one", "interested stakeholders", "random pets"]'::jsonb,2,'Showcases share work with stakeholders.','original'),
('127.453.d.6.C',4,'Before presenting a portfolio to an employer, a student should check that every item is current, organized, and free of:','["color", "pages", "samples", "errors"]'::jsonb,3,'Quality control matters.','original'),
('127.453.d.6.B.i',3,'A portfolio section for achievements could display a certificate showing the student passed an industry exam, which documents her:','["attainment of a credential", "birth date", "lunch choice", "travel history"]'::jsonb,0,'Credentials document attainment.','original'),
('127.453.d.6.B.i',4,'An organized portfolio places certificates and test results together so a reviewer can quickly see the student''s:','["height", "qualifications", "hobbies only", "favorite foods"]'::jsonb,1,'Organization helps reviewers.','original'),
('127.453.d.6.B.ii',3,'A portfolio can list professional licenses and the dates they expire, which shows employers that the student is:','["unsafe", "too young", "legally authorized", "unpaid"]'::jsonb,2,'Licenses show authorization.','original'),
('127.453.d.6.B.ii',4,'A student who earned an OSHA safety card should place a copy under licensures and:','["coupons", "recipes", "rumors", "certifications"]'::jsonb,3,'Safety cards are credentials.','original'),
('127.453.d.6.B.iii',3,'A newspaper clipping about a student''s winning engineering project would be placed in the portfolio''s:','["recognitions section", "bill section", "budget section", "complaint section"]'::jsonb,0,'Clippings record recognition.','original'),
('127.453.d.6.B.iii',4,'Honor society membership and scholarship letters are examples of:','["warnings", "recognitions", "fines", "liabilities"]'::jsonb,1,'Honors belong in the recognition area.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_69_v1'
from (values
('127.453.d.6.B.iv',3,'Documentation of a job shadow with an engineer, with a short reflection on what the student learned, is an example of:','["a grade change", "a bus pass", "extended learning", "a school rule"]'::jsonb,2,'Reflections add depth.','original'),
('127.453.d.6.B.iv',4,'A summer program at a university lab can be described in the portfolio as an:','["free vacation", "personal secret", "unrelated event", "extended learning experience"]'::jsonb,3,'Programs outside class show growth.','original'),
('127.453.d.6.B.v',3,'A one-paragraph overview of a student''s year-long engineering capstone, placed at the front of its section, is an:','["abstract of the project", "menu", "parking permit", "order form"]'::jsonb,0,'Abstracts help readers scan.','original'),
('127.453.d.6.B.v',4,'A good abstract is short and states the project goal, the approach, and the:','["shipping label", "main outcome", "complete code", "full budget"]'::jsonb,1,'Abstracts summarize key facts.','original'),
('127.453.d.6.B.vi',3,'A resume in a portfolio should be limited to one clear page and organized under headings such as education, skills, and:','["games", "rumors", "experience", "jokes"]'::jsonb,2,'Resumes use standard sections.','original'),
('127.453.d.6.B.vi',4,'A resume that is carefully proofread and tailored to an engineering internship makes a better:','["tax return", "bus route", "lunch", "first impression"]'::jsonb,3,'Careful resumes impress employers.','original'),
('127.453.d.6.B.vii',3,'Photos of a student''s welded frame, a CAD drawing, and a test video link are all:','["work samples", "rumors", "coupons", "tickets"]'::jsonb,0,'Samples show skill.','original'),
('127.453.d.6.B.vii',4,'Selecting only the best, most relevant work samples for a portfolio shows good:','["luck", "judgment", "volume", "speed"]'::jsonb,1,'Curating shows quality over quantity.','original'),
('127.453.d.6.B.viii',3,'A rating sheet filled out by an internship supervisor about attendance, skills, and attitude is a performance:','["coupon", "ticket", "evaluation", "menu"]'::jsonb,2,'Evaluations rate performance.','original'),
('127.453.d.6.B.viii',4,'A supervisor''s written comment that the intern is reliable and learns quickly adds credibility because it comes from:','["the student herself", "no one", "a stranger", "a third party"]'::jsonb,3,'Outside views add credibility.','original'),
('127.453.d.7.A',3,'A student prepares a poster and a three-minute talk to share her internship project at a science and engineering showcase. This is a:','["professional presentation", "grade rumor", "tax form", "private diary"]'::jsonb,0,'Presentations share findings.','original'),
('127.453.d.7.A',4,'To make a poster easy to read from a few feet away, a student should use a clear title and:','["tiny paragraphs", "large, simple graphics", "dark backgrounds only", "many fonts"]'::jsonb,1,'Posters need readability.','original'),
('127.453.d.7.B',3,'A student presenting to a panel of engineers can use more technical detail than when presenting to:','["a licensing board", "a professional society", "a group of younger students", "a research lab"]'::jsonb,2,'Match detail to the audience.','original'),
('127.453.d.7.B',4,'Arranging for a projector, testing the slides, and confirming the time slot are parts of:','["ending the project", "closing the school", "skipping the talk", "coordinating the presentation"]'::jsonb,3,'Preparation prevents problems.','original'),
('127.453.d.7.C',3,'A presenter who avoids filler words, speaks at a steady pace, and ends on time is speaking:','["professionally", "sloppily", "randomly", "carelessly"]'::jsonb,0,'Polished delivery matters.','original'),
('127.453.d.7.C',4,'When explaining a data table in a presentation, the best approach is to highlight the:','["entire table aloud", "key trend in a sentence", "raw numbers one by one", "unrelated facts"]'::jsonb,1,'Conciseness aids understanding.','original'),
('127.453.d.7.D',3,'A student records her practice talk, watches it, and lists what to improve. This is a way to analyze:','["her friends'' hobbies", "last year''s budget", "her own performance", "the weather"]'::jsonb,2,'Self-review improves delivery.','original'),
('127.453.d.7.D',4,'After a showcase, three judges say the student''s charts were unclear. She should respond by:','["ignoring the comments", "blaming the judges", "deleting the project", "redesigning the charts"]'::jsonb,3,'Feedback should lead to action.','original'),
('127.461.d.5',3,'A student who wants to become a nurse should plan to take strong courses in science, math, and:','["English and communication", "only gym classes", "no lab classes", "only art classes"]'::jsonb,0,'Health careers require academic preparation.','original'),
('127.461.d.5',4,'Many health science careers require a high school diploma, then further training or a degree. This shows why students need to plan their:','["vacations", "academic preparation", "wardrobes", "playlists"]'::jsonb,1,'Education leads to careers.','original'),
('127.461.d.1.A',3,'A nurse reads a dose in milligrams, but the supply is labeled in grams. She must use unit conversion to change between:','["languages", "time zones", "systems of measurement", "blood types"]'::jsonb,2,'Conversions prevent dosing mistakes.','original'),
('127.461.d.1.A',4,'A patient weighs 154 pounds. Using 1 kg = 2.2 lb, the weight in kilograms is:','["7", "338.8", "3.4", "70"]'::jsonb,3,'154 / 2.2 = 70.','original'),
('127.461.d.1.B',3,'A clinic charts a patient''s temperature over three days. The chart helps staff see whether the fever is:','["going up or down", "a prize", "a contract", "a rumor"]'::jsonb,0,'Graphs show trends in data.','original'),
('127.461.d.1.B',4,'A graph shows a child''s weight at each visit. A line that rises steadily suggests the child is:','["losing weight", "gaining weight over time", "moving away", "staying exactly the same"]'::jsonb,1,'Trends appear in graphs.','original'),
('127.461.d.1.C',3,'A technician reads a manual explaining how to clean an ultrasound probe. Understanding this kind of text is called interpreting:','["poetry", "fiction", "technical material", "advertising"]'::jsonb,2,'Manuals give precise steps.','original'),
('127.461.d.1.C',4,'A nurse reads a package insert that lists side effects and storage rules. The insert is useful because it gives:','["slogans", "entertainment", "opinions", "accurate product information"]'::jsonb,3,'Inserts guide safe use.','original'),
('127.461.d.1.D',3,'At the end of a shift, a nurse summarizes a patient''s changes in a clear note. This is an example of writing:','["a report or summary", "a novel", "a joke", "a poem"]'::jsonb,0,'Clear writing supports care.','original'),
('127.461.d.1.D',4,'A good patient summary is accurate, brief, and organized so the next shift can quickly find the:','["office gossip", "key facts", "parking rules", "lunch menu"]'::jsonb,1,'Summaries must be useful.','original'),
('127.461.d.1.E',3,'A student will explain hand hygiene to classmates. Planning an effective talk includes knowing the audience and rehearsing the:','["wrong order", "jokes only", "main points", "tiny details"]'::jsonb,2,'Preparation improves delivery.','original'),
('127.461.d.1.E',4,'To keep an oral presentation on health topics clear, a speaker should use an introduction, key points, and a:','["secret", "quiz grade", "price list", "conclusion"]'::jsonb,3,'Good talks have a structure.','original'),
('127.461.d.1.F',3,'A nurse says the patient has high blood pressure instead of saying her pressure is up there somewhere. The nurse is using:','["precise language", "silence", "vague language", "slang only"]'::jsonb,0,'Precision avoids errors.','original'),
('127.461.d.1.F',4,'Telling a patient exactly when to take a medicine and with what, rather than saying later, is an example of:','["delay", "clear communication", "guessing", "avoidance"]'::jsonb,1,'Clear instructions protect patients.','original'),
('127.461.d.1.G',3,'The body keeps its temperature steady by sweating when hot and shivering when cold. This balance is called:','["inflation", "evolution", "homeostasis", "erosion"]'::jsonb,2,'Homeostasis keeps stable conditions.','original'),
('127.461.d.1.G',4,'When blood sugar rises after a meal, the pancreas releases insulin to bring it back down. This is a chemical process that helps maintain:','["a fashion trend", "a school schedule", "a bank account", "balance in the body"]'::jsonb,3,'Hormones regulate balance.','original'),
('127.461.d.1.H',3,'A caregiver bends at the knees and keeps the patient close when lifting. Using good body mechanics protects the caregiver''s:','["back", "car", "phone", "hair"]'::jsonb,0,'Proper mechanics prevent injury.','original'),
('127.461.d.1.H',4,'A wide base of support helps a person stay balanced when moving a patient because it lowers the chance of:','["reading", "falling", "sleeping", "laughing"]'::jsonb,1,'Balance depends on base of support.','original'),
('127.461.d.1.I',3,'In Maslow''s hierarchy, needs like food, water, and sleep are at the bottom and are called:','["esteem needs", "belonging", "physiological needs", "self-actualization"]'::jsonb,2,'Basic survival needs come first.','original'),
('127.461.d.1.I',4,'A patient who feels safe, loved, and respected is meeting needs higher in the hierarchy than food and rest, such as:','["shelter only", "water", "oxygen", "belonging and esteem"]'::jsonb,3,'Higher needs follow basic needs.','original'),
('127.461.d.1.J',3,'Human development from birth to old age is divided into stages. The stage between childhood and adulthood is:','["adolescence", "toddlerhood", "late adulthood", "infancy"]'::jsonb,0,'Teen years are adolescence.','original'),
('127.461.d.1.J',4,'A health worker who works with older adults should understand the changes of late adulthood, such as slower:','["tooth eruption", "reaction time", "first steps", "growth spurts"]'::jsonb,1,'Aging changes needs.','original'),
('127.461.d.1.K',3,'Eating balanced meals, exercising, and sleeping enough are habits that support lifelong:','["debt", "fame", "health and wellness", "boredom"]'::jsonb,2,'Healthy habits help at every age.','original'),
('127.461.d.1.K',4,'Wellness means more than the absence of illness. It includes physical, mental, and social:','["costs", "rumors", "errors", "well-being"]'::jsonb,3,'Wellness is broad.','original'),
('127.461.d.1.L',3,'A health worker greets a patient warmly, listens, and explains things simply. These skills help build a healthy:','["relationship with the patient", "bank balance", "budget", "parking space"]'::jsonb,0,'Good communication builds trust.','original'),
('127.461.d.1.L',4,'Active listening and an open attitude help a care team keep relationships healthy because patients feel:','["ignored", "respected and heard", "judged", "rushed"]'::jsonb,1,'Respect improves cooperation.','original'),
('127.461.d.1.M',3,'In the past, doctors sometimes treated illness by draining blood. Studying how medicine has changed over time is learning the:','["map of a city", "rules of a sport", "history of health care", "recipe for bread"]'::jsonb,2,'History shows progress.','original'),
('127.461.d.1.M',4,'The discovery of germs in the 1800s led to cleaner hospitals and fewer infections. This is a key moment in the history of:','["fashion", "farming only", "music", "health care"]'::jsonb,3,'Germ theory changed medicine.','original'),
('127.461.d.1.N',3,'Hospitals, clinics, and pharmacies employ millions of people and spend billions each year. Health services therefore have a large effect on the:','["economy", "moon", "calendar", "weather"]'::jsonb,0,'Health care is a major industry.','original'),
('127.461.d.1.N',4,'When a community has a new hospital, jobs and local business often increase. This shows health services can help a community''s:','["weather", "economic growth", "school colors", "street names"]'::jsonb,1,'Hospitals bring jobs.','original'),
('127.461.d.1.O',3,'Laws about patient privacy, medicine safety, and insurance are made by local, state, and national:','["game shows", "fan clubs", "government", "sports leagues"]'::jsonb,2,'Governments regulate health care.','original'),
('127.461.d.1.O',4,'Medicare and Medicaid are national programs that help pay for care. They are examples of government''s effect on:','["sports rules", "fashion", "road repair", "health care access"]'::jsonb,3,'Government programs shape access.','original'),
('127.461.d.1.P',3,'A hospital offers translators and respects different religious customs. This shows how diverse cultures influence modern:','["health care", "architecture only", "traffic", "weather"]'::jsonb,0,'Culture shapes care.','original'),
('127.461.d.1.P',4,'Many medicines today began as plant remedies used by early cultures. This shows how cultural traditions have influenced:','["road signs", "modern medicine", "sports uniforms", "movie plots"]'::jsonb,1,'Traditional knowledge influenced drugs.','original'),
('127.461.d.1.Q',3,'Acupuncture developed in China, and herbal healing is practiced in many societies. Comparing these shows that cultures use different:','["languages for math", "school buses", "approaches to healing", "kinds of weather"]'::jsonb,2,'Cultures treat illness differently.','original'),
('127.461.d.1.Q',4,'A health worker who learns about a patient''s cultural health beliefs can offer care that is:','["secret", "expensive", "rushed", "respectful and effective"]'::jsonb,3,'Understanding culture improves care.','original'),
('127.461.d.2.A',3,'Making eye contact, speaking clearly, and listening are parts of effective communication. Interrupting and mumbling are parts of:','["non-effective communication", "active speaking", "good listening", "teamwork"]'::jsonb,0,'Behaviors shape communication.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
